    }
    if (parsed is List && parsed.length >= 2 && parsed[0] is String) {
      final toolName = parsed[0] as String;
      return _timed(
        toolName,
        () => _toolCallResult(
          () => _execute(toolName, _castArgs(parsed[1])),
        ),
