        '${DateTime.now().microsecondsSinceEpoch}.sh');
    script.writeAsStringSync('{\n$command\n} 2>&1\n');
    try {
      return Process.runSync('/bin/sh', [script.path],
          workingDirectory: workDir, environment: env);
    } finally {
      try {
        script.deleteSync();
