  final String path;
  if (parsed is String) {
    path = parsed;
  } else if (parsed is Map && parsed['path'] is String) {
    path = parsed['path'] as String;
  } else {
    return _jsError(
      'file_read expects a path string or {path: <string>} as its '
      'argument (got ${parsed == null ? 'no argument' : jsonEncode(parsed)})',
    );
